+func parseSprintPerformanceArgs(args []string) (sprintPerformanceCommand, error) {
+	command := sprintPerformanceCommand{Action: "run"}
+	if len(args) > 0 && !strings.HasPrefix(args[0], "-") {
+		command.Action = args[0]
+		args = args[1:]
+	}
+	for _, arg := range args {
+		switch arg {
+		case "--dry-run":
+			if command.Action != "run" {
+				return command, errors.New("--dry-run cannot be combined with a performance action")
+			}
+			command.Action = "dry-run"
+		case "--json":
+			command.JSON = true
+		case "--yes":
+			command.Yes = true
+		default:
+			return command, fmt.Errorf("unknown performance argument %q", arg)
+		}
+	}
+	switch command.Action {
+	case "run", "dry-run", "status", "resume", "cancel", "recover":
+	default:
+		return command, fmt.Errorf("unknown performance action %q", command.Action)
+	}
+	if (command.Action == "run" || command.Action == "resume") && !command.Yes {
+		return command, fmt.Errorf("performance %s requires --yes", command.Action)
+	}
+	if command.Yes && command.Action != "run" && command.Action != "resume" {
+		return command, fmt.Errorf("--yes is valid only with performance run or resume")
+	}
+	return command, nil
+}
