+		for _, missing := range result.Missing {
+			fmt.Fprintf(deps.stdout, "- missing: %s\n", missing)
+		}
+	case PerformanceStatusResult:
+		fmt.Fprintf(deps.stdout, "Performance %s: %s/%s\nPolicy: %s\nPhase: %s\nFresh: %t\nOutcome: %s\nTargets: %d\nNext: %s\n", action, result.Project, result.Sprint, result.PolicyMode, result.Phase, result.Fresh, operationFirstNonEmpty(result.Outcome, "none"), len(result.Targets), result.NextAction)
+		for _, target := range result.Targets {
+			fmt.Fprintf(deps.stdout, "- %s: %s %s %s %s (%s, %s) outcome=%s\n", target.ID, target.Metric, target.Comparator, target.Value, target.Unit, target.Gate, target.Basis, operationFirstNonEmpty(target.Outcome, "pending"))
+		}
+	default:
+		fmt.Fprintf(deps.stdout, "Performance %s\n", action)
+	}
+}
